let file = """{"version":3,"file":"LightInfo-C47mAN4w.js","names":["$t","$t","$t"],"sources":["../../src/components/lightInfo/LightInfoLightEditor.vue","../../src/components/lightInfo/LightInfoLightEditor.vue","../../src/extensions/core/lightInfo/LightInfoOverlay.ts","../../src/extensions/core/lightInfo/lightTransform.ts","../../src/extensions/core/lightInfo/LightInfoViewport.ts","../../src/components/lightInfo/LightInfoViewportToolbar.vue","../../src/components/lightInfo/LightInfoViewportToolbar.vue","../../src/components/lightInfo/useLightInfo.ts","../../src/components/lightInfo/LightInfo.vue","../../src/components/lightInfo/LightInfo.vue"],"sourcesContent":["<template>\n  <div\n    class=\"flex flex-col gap-2 rounded-sm bg-node-component-surface p-2 text-xs\"\n  >\n    <ToggleGroup\n      type=\"single\"\n      :model-value=\"light.type\"\n      class=\"w-full min-w-0 rounded-md bg-component-node-widget-background p-1\"\n      @update:model-value=\"onTypeChange\"\n    >\n      <ToggleGroupItem\n        v-for=\"type in LIGHT_TYPES\"\n        :key=\"type\"\n        :value=\"type\"\n        size=\"sm\"\n        class=\"flex-1 px-2\"\n      >\n        {{ $t(LIGHT_TYPE_LABEL_KEYS[type]) }}\n      </ToggleGroupItem>\n    </ToggleGroup>\n    <div\n      :class=\"\n        cn(\n          'grid items-center gap-x-2 gap-y-1',\n          compact\n            ? 'grid-cols-[auto_minmax(0,1fr)]'\n            : 'grid-cols-[auto_minmax(0,1fr)_auto_minmax(0,1fr)]'\n        )\n      \"\n    >\n      <label :class=\"FIELD_LABEL_CLASS\">{{ $t('lightInfo.color') }}</label>\n      <ColorPicker\n        :model-value=\"light.color\"\n        :alpha=\"false\"\n        :aria-label=\"$t('lightInfo.color')\"\n        @update:model-value=\"(color) => emit('update', { color })\"\n      />\n      <label :class=\"FIELD_LABEL_CLASS\">\n        {{ $t('lightInfo.castShadow') }}\n      </label>\n      <Switch\n        :model-value=\"light.castShadow !== false\"\n        :aria-label=\"$t('lightInfo.castShadow')\"\n        @update:model-value=\"(castShadow) => emit('update', { castShadow })\"\n      />\n      <template v-for=\"field in numberFields\" :key=\"field.key\">\n        <label :class=\"FIELD_LABEL_CLASS\">{{ $t(field.labelKey) }}</label>\n        <ScrubableNumberInput\n          :model-value=\"field.value\"\n          :display-value=\"formatField(field.key, field.value)\"\n          :input-attrs=\"{ 'aria-label': $t(field.labelKey) }\"\n          :min=\"field.min\"\n          :max=\"field.max\"\n          :step=\"field.step\"\n          @update:model-value=\"(value) => setNumber(field.key, value)\"\n        />\n      </template>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ScrubableNumberInput from '@/components/common/ScrubableNumberInput.vue'\nimport ColorPicker from '@/components/ui/color-picker/ColorPicker.vue'\nimport Switch from '@/components/ui/switch/Switch.vue'\nimport { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'\nimport {\n  LIGHT_TYPES,\n  LIGHT_TYPE_LABEL_KEYS\n} from '@/extensions/core/lightInfo/types'\nimport type {\n  LightInfoEntry,\n  LightInfoType\n} from '@/extensions/core/lightInfo/types'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ntype NumberField =\n  | 'intensity'\n  | 'range'\n  | 'innerConeAngle'\n  | 'outerConeAngle'\n  | 'radius'\n\ninterface NumberFieldSpec {\n  key: NumberField\n  labelKey: string\n  value: number\n  min: number\n  max?: number\n  step: number\n}\n\nconst FIELD_LABEL_CLASS =\n  'content-center truncate text-node-component-slot-text'\n\nconst { light, compact } = defineProps<{\n  light: LightInfoEntry\n  compact: boolean\n}>()\n\nconst emit = defineEmits<{\n  update: [patch: Partial<LightInfoEntry>]\n  changeType: [type: LightInfoType]\n}>()\n\nconst { locale } = useI18n()\n\nconst numberFields = computed<NumberFieldSpec[]>(() => {\n  const directional = light.type === 'directional'\n  const fields: NumberFieldSpec[] = [\n    {\n      key: 'intensity',\n      labelKey: 'lightInfo.intensity',\n      value: light.intensity,\n      min: 0,\n      step: 0.1\n    },\n    {\n      key: 'radius',\n      labelKey: directional ? 'lightInfo.angle' : 'lightInfo.size',\n      value: light.radius ?? 0,\n      min: 0,\n      step: directional ? 0.1 : 0.05\n    }\n  ]\n  if (!directional) {\n    fields.push({\n      key: 'range',\n      labelKey: 'lightInfo.range',\n      value: light.range ?? 0,\n      min: 0,\n      step: 0.5\n    })\n  }\n  if (light.type === 'spot') {\n    fields.push(\n      {\n        key: 'innerConeAngle',\n        labelKey: 'lightInfo.innerCone',\n        value: light.innerConeAngle ?? 30,\n        min: 0,\n        max: 90,\n        step: 1\n      },\n      {\n        key: 'outerConeAngle',\n        labelKey: 'lightInfo.outerCone',\n        value: light.outerConeAngle ?? 45,\n        min: 1,\n        max: 90,\n        step: 1\n      }\n    )\n  }\n  return fields\n})\n\nfunction onTypeChange(value: unknown) {\n  const type = LIGHT_TYPES.find((candidate) => candidate === value)\n  if (type) emit('changeType', type)\n}\n\nfunction fieldDecimals(field: NumberField): number {\n  if (field === 'innerConeAngle' || field === 'outerConeAngle') return 0\n  if (field === 'radius' && light.type !== 'directional') return 2\n  return 1\n}\n\nfunction formatField(field: NumberField, value: number): string {\n  return new Intl.NumberFormat(locale.value, {\n    maximumFractionDigits: fieldDecimals(field),\n    useGrouping: false\n  }).format(value)\n}\n\nfunction setNumber(field: NumberField, raw: number) {\n  if (!Number.isFinite(raw)) return\n  const value = Number(raw.toFixed(fieldDecimals(field)))\n  if (field === 'innerConeAngle') {\n    emit('update', {\n      innerConeAngle: Math.min(value, light.outerConeAngle ?? 45)\n    })\n    return\n  }\n  if (field === 'outerConeAngle') {\n    emit('update', {\n      outerConeAngle: value,\n      innerConeAngle: Math.min(light.innerConeAngle ?? 30, value)\n    })\n    return\n  }\n  emit('update', { [field]: value })\n}\n</script>\n","<template>\n  <div\n    class=\"flex flex-col gap-2 rounded-sm bg-node-component-surface p-2 text-xs\"\n  >\n    <ToggleGroup\n      type=\"single\"\n      :model-value=\"light.type\"\n      class=\"w-full min-w-0 rounded-md bg-component-node-widget-background p-1\"\n      @update:model-value=\"onTypeChange\"\n    >\n      <ToggleGroupItem\n        v-for=\"type in LIGHT_TYPES\"\n        :key=\"type\"\n        :value=\"type\"\n        size=\"sm\"\n        class=\"flex-1 px-2\"\n      >\n        {{ $t(LIGHT_TYPE_LABEL_KEYS[type]) }}\n      </ToggleGroupItem>\n    </ToggleGroup>\n    <div\n      :class=\"\n        cn(\n          'grid items-center gap-x-2 gap-y-1',\n          compact\n            ? 'grid-cols-[auto_minmax(0,1fr)]'\n            : 'grid-cols-[auto_minmax(0,1fr)_auto_minmax(0,1fr)]'\n        )\n      \"\n    >\n      <label :class=\"FIELD_LABEL_CLASS\">{{ $t('lightInfo.color') }}</label>\n      <ColorPicker\n        :model-value=\"light.color\"\n        :alpha=\"false\"\n        :aria-label=\"$t('lightInfo.color')\"\n        @update:model-value=\"(color) => emit('update', { color })\"\n      />\n      <label :class=\"FIELD_LABEL_CLASS\">\n        {{ $t('lightInfo.castShadow') }}\n      </label>\n      <Switch\n        :model-value=\"light.castShadow !== false\"\n        :aria-label=\"$t('lightInfo.castShadow')\"\n        @update:model-value=\"(castShadow) => emit('update', { castShadow })\"\n      />\n      <template v-for=\"field in numberFields\" :key=\"field.key\">\n        <label :class=\"FIELD_LABEL_CLASS\">{{ $t(field.labelKey) }}</label>\n        <ScrubableNumberInput\n          :model-value=\"field.value\"\n          :display-value=\"formatField(field.key, field.value)\"\n          :input-attrs=\"{ 'aria-label': $t(field.labelKey) }\"\n          :min=\"field.min\"\n          :max=\"field.max\"\n          :step=\"field.step\"\n          @update:model-value=\"(value) => setNumber(field.key, value)\"\n        />\n      </template>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ScrubableNumberInput from '@/components/common/ScrubableNumberInput.vue'\nimport ColorPicker from '@/components/ui/color-picker/ColorPicker.vue'\nimport Switch from '@/components/ui/switch/Switch.vue'\nimport { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'\nimport {\n  LIGHT_TYPES,\n  LIGHT_TYPE_LABEL_KEYS\n} from '@/extensions/core/lightInfo/types'\nimport type {\n  LightInfoEntry,\n  LightInfoType\n} from '@/extensions/core/lightInfo/types'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ntype NumberField =\n  | 'intensity'\n  | 'range'\n  | 'innerConeAngle'\n  | 'outerConeAngle'\n  | 'radius'\n\ninterface NumberFieldSpec {\n  key: NumberField\n  labelKey: string\n  value: number\n  min: number\n  max?: number\n  step: number\n}\n\nconst FIELD_LABEL_CLASS =\n  'content-center truncate text-node-component-slot-text'\n\nconst { light, compact } = defineProps<{\n  light: LightInfoEntry\n  compact: boolean\n}>()\n\nconst emit = defineEmits<{\n  update: [patch: Partial<LightInfoEntry>]\n  changeType: [type: LightInfoType]\n}>()\n\nconst { locale } = useI18n()\n\nconst numberFields = computed<NumberFieldSpec[]>(() => {\n  const directional = light.type === 'directional'\n  const fields: NumberFieldSpec[] = [\n    {\n      key: 'intensity',\n      labelKey: 'lightInfo.intensity',\n      value: light.intensity,\n      min: 0,\n      step: 0.1\n    },\n    {\n      key: 'radius',\n      labelKey: directional ? 'lightInfo.angle' : 'lightInfo.size',\n      value: light.radius ?? 0,\n      min: 0,\n      step: directional ? 0.1 : 0.05\n    }\n  ]\n  if (!directional) {\n    fields.push({\n      key: 'range',\n      labelKey: 'lightInfo.range',\n      value: light.range ?? 0,\n      min: 0,\n      step: 0.5\n    })\n  }\n  if (light.type === 'spot') {\n    fields.push(\n      {\n        key: 'innerConeAngle',\n        labelKey: 'lightInfo.innerCone',\n        value: light.innerConeAngle ?? 30,\n        min: 0,\n        max: 90,\n        step: 1\n      },\n      {\n        key: 'outerConeAngle',\n        labelKey: 'lightInfo.outerCone',\n        value: light.outerConeAngle ?? 45,\n        min: 1,\n        max: 90,\n        step: 1\n      }\n    )\n  }\n  return fields\n})\n\nfunction onTypeChange(value: unknown) {\n  const type = LIGHT_TYPES.find((candidate) => candidate === value)\n  if (type) emit('changeType', type)\n}\n\nfunction fieldDecimals(field: NumberField): number {\n  if (field === 'innerConeAngle' || field === 'outerConeAngle') return 0\n  if (field === 'radius' && light.type !== 'directional') return 2\n  return 1\n}\n\nfunction formatField(field: NumberField, value: number): string {\n  return new Intl.NumberFormat(locale.value, {\n    maximumFractionDigits: fieldDecimals(field),\n    useGrouping: false\n  }).format(value)\n}\n\nfunction setNumber(field: NumberField, raw: number) {\n  if (!Number.isFinite(raw)) return\n  const value = Number(raw.toFixed(fieldDecimals(field)))\n  if (field === 'innerConeAngle') {\n    emit('update', {\n      innerConeAngle: Math.min(value, light.outerConeAngle ?? 45)\n    })\n    return\n  }\n  if (field === 'outerConeAngle') {\n    emit('update', {\n      outerConeAngle: value,\n      innerConeAngle: Math.min(light.innerConeAngle ?? 30, value)\n    })\n    return\n  }\n  emit('update', { [field]: value })\n}\n</script>\n","import * as THREE from 'three'\n\nimport type { SceneOverlay } from '@/extensions/core/load3d/interfaces'\n\nimport { cloneLights, lightTarget } from './types'\nimport type { LightInfoEntry, LightInfoType } from './types'\n\nconst SPHERE_RADIUS = 1\nconst SPHERE_SEGMENTS = 64\nconst SPHERE_COLOR = 0xcccccc\nconst GROUND_SIZE = 40\nconst GROUND_Y = -1\nconst GROUND_COLOR = 0x8a8a8a\nconst AMBIENT_INTENSITY = 0.2\nconst AMBIENT_SKY_COLOR = 0xffffff\nconst AMBIENT_GROUND_COLOR = 0x808080\nconst MARKER_RADIUS = 0.1\nconst MARKER_SELECTED_SCALE = 1.4\nconst SHADOW_MAP_SIZE = 1024\nconst SHADOW_BIAS = -0.0005\nconst DIRECTIONAL_SHADOW_HALF = GROUND_SIZE / 2\nconst SHADOW_BLUR_TEXELS_PER_UNIT = 20\nconst SHADOW_BLUR_TEXELS_PER_DEGREE = 2\n\nconst DEG2RAD = Math.PI / 180\n\ntype SceneLight = THREE.DirectionalLight | THREE.PointLight | THREE.SpotLight\n\ninterface LightRig {\n  type: LightInfoType\n  light: SceneLight\n  helper: THREE.Object3D & { update?: () => void; dispose: () => void }\n  marker: THREE.Mesh\n}\n\nfunction createSceneLight(type: LightInfoType): SceneLight {\n  if (type === 'point') return new THREE.PointLight()\n  if (type === 'spot') return new THREE.SpotLight()\n  return new THREE.DirectionalLight()\n}\n\nfunction createHelper(light: SceneLight): LightRig['helper'] {\n  if (light instanceof THREE.PointLight) {\n    return new THREE.PointLightHelper(light, 0.3)\n  }\n  if (light instanceof THREE.SpotLight) {\n    return new THREE.SpotLightHelper(light)\n  }\n  return new THREE.DirectionalLightHelper(light, 0.5)\n}\n\nexport class LightInfoOverlay implements SceneOverlay {\n  private scene: THREE.Scene | null = null\n  private lights: LightInfoEntry[] = []\n  private selectedIndex = -1\n\n  private readonly studioGroup: THREE.Group\n  private readonly sphere: THREE.Mesh\n  private readonly ground: THREE.Mesh\n  private readonly ambientLight: THREE.HemisphereLight\n  private rigs: LightRig[] = []\n\n  private helpersOn = true\n  private disposed = false\n\n  constructor(initialLights: LightInfoEntry[] = []) {\n    this.lights = cloneLights(initialLights)\n    this.selectedIndex = this.lights.length ? 0 : -1\n\n    this.sphere = new THREE.Mesh(\n      new THREE.SphereGeometry(SPHERE_RADIUS, SPHERE_SEGMENTS, SPHERE_SEGMENTS),\n      new THREE.MeshStandardMaterial({\n        color: SPHERE_COLOR,\n        roughness: 0.8,\n        metalness: 0\n      })\n    )\n    this.sphere.castShadow = true\n    this.sphere.receiveShadow = true\n\n    this.ground = new THREE.Mesh(\n      new THREE.PlaneGeometry(GROUND_SIZE, GROUND_SIZE),\n      new THREE.MeshStandardMaterial({\n        color: GROUND_COLOR,\n        roughness: 1,\n        metalness: 0\n      })\n    )\n    this.ground.rotation.x = -Math.PI / 2\n    this.ground.position.y = GROUND_Y\n    this.ground.receiveShadow = true\n\n    this.studioGroup = new THREE.Group()\n    this.studioGroup.name = 'LightInfoStudio'\n    this.studioGroup.add(this.sphere)\n    this.studioGroup.add(this.ground)\n\n    this.ambientLight = new THREE.HemisphereLight(\n      AMBIENT_SKY_COLOR,\n      AMBIENT_GROUND_COLOR,\n      AMBIENT_INTENSITY\n    )\n  }\n\n  attach(scene: THREE.Scene): void {\n    this.scene = scene\n    scene.add(this.studioGroup)\n    scene.add(this.ambientLight)\n    this.rebuildRigs()\n    this.lights.forEach((light, i) => this.applyLightToRig(light, i))\n    this.refreshHelperVisibility()\n    this.updateHelpers()\n  }\n\n  detach(): void {\n    if (!this.scene) return\n    this.removeRigs()\n    this.scene.remove(this.studioGroup)\n    this.scene.remove(this.ambientLight)\n    this.scene = null\n  }\n\n  update(_delta: number): void {\n    this.updateHelpers()\n  }\n\n  dispose(): void {\n    if (this.disposed) return\n    this.disposed = true\n    this.removeRigs()\n    this.sphere.geometry.dispose()\n    ;(this.sphere.material as THREE.Material).dispose()\n    this.ground.geometry.dispose()\n    ;(this.ground.material as THREE.Material).dispose()\n  }\n\n  getLights(): LightInfoEntry[] {\n    return cloneLights(this.lights)\n  }\n\n  getSelectedIndex(): number {\n    return this.selectedIndex\n  }\n\n  getSelectedLight(): LightInfoEntry | null {\n    if (this.selectedIndex < 0 || this.selectedIndex >= this.lights.length) {\n      return null\n    }\n    return cloneLights([this.lights[this.selectedIndex]])[0]\n  }\n\n  applyLights(lights: LightInfoEntry[], selectedIndex: number): void {\n    this.lights = cloneLights(lights)\n    this.selectedIndex = Math.min(selectedIndex, this.lights.length - 1)\n    if (!this.scene) return\n    const typesMatch =\n      this.rigs.length === this.lights.length &&\n      this.rigs.every((rig, i) => rig.type === this.lights[i].type)\n    if (!typesMatch) this.rebuildRigs()\n    this.lights.forEach((light, i) => this.applyLightToRig(light, i))\n    this.refreshHelperVisibility()\n    this.updateHelpers()\n  }\n\n  markerMeshes(): THREE.Object3D[] {\n    return this.rigs.map((rig) => rig.marker)\n  }\n\n  setHelpersVisible(visible: boolean): void {\n    this.helpersOn = visible\n    this.refreshHelperVisibility()\n  }\n\n  private rebuildRigs(): void {\n    this.removeRigs()\n    const scene = this.scene\n    if (!scene) return\n    this.rigs = this.lights.map((entry, i) => {\n      const light = createSceneLight(entry.type)\n      light.castShadow = true\n      light.shadow.mapSize.set(SHADOW_MAP_SIZE, SHADOW_MAP_SIZE)\n      light.shadow.bias = SHADOW_BIAS\n      if (light instanceof THREE.DirectionalLight) {\n        light.shadow.camera.left = -DIRECTIONAL_SHADOW_HALF\n        light.shadow.camera.right = DIRECTIONAL_SHADOW_HALF\n        light.shadow.camera.top = DIRECTIONAL_SHADOW_HALF\n        light.shadow.camera.bottom = -DIRECTIONAL_SHADOW_HALF\n      }\n      const marker = new THREE.Mesh(\n        new THREE.SphereGeometry(MARKER_RADIUS, 16, 16),\n        new THREE.MeshBasicMaterial({ color: 0xffffff })\n      )\n      marker.name = `LightInfoEmitterMarker${i}`\n      const helper = createHelper(light)\n      scene.add(light)\n      if (hasTargetObject(light)) scene.add(light.target)\n      scene.add(marker)\n      scene.add(helper)\n      return { type: entry.type, light, helper, marker }\n    })\n  }\n\n  private removeRigs(): void {\n    for (const rig of this.rigs) {\n      this.scene?.remove(rig.light)\n      if (hasTargetObject(rig.light)) this.scene?.remove(rig.light.target)\n      this.scene?.remove(rig.marker)\n      this.scene?.remove(rig.helper)\n      rig.helper.dispose()\n      rig.marker.geometry.dispose()\n      ;(rig.marker.material as THREE.Material).dispose()\n      rig.light.dispose()\n    }\n    this.rigs = []\n  }\n\n  private applyLightToRig(entry: LightInfoEntry, index: number): void {\n    const rig = this.rigs.at(index)\n    if (!rig) return\n    const color = new THREE.Color(entry.color)\n    const { light, marker } = rig\n\n    light.color.copy(color)\n    light.intensity = entry.intensity\n    light.position.set(entry.position.x, entry.position.y, entry.position.z)\n    light.castShadow = entry.castShadow !== false\n    light.shadow.radius = 1 + shadowBlurTexels(entry)\n\n    const target = lightTarget(entry)\n    if (light instanceof THREE.SpotLight) {\n      light.target.position.set(target.x, target.y, target.z)\n      light.target.updateMatrixWorld(true)\n      light.distance = entry.range ?? 0\n      light.angle = (entry.outerConeAngle ?? 45) * DEG2RAD\n      light.penumbra = spotPenumbra(entry)\n    } else if (light instanceof THREE.PointLight) {\n      light.distance = entry.range ?? 0\n    } else {\n      light.target.position.set(target.x, target.y, target.z)\n      light.target.updateMatrixWorld(true)\n    }\n    light.updateMatrixWorld(true)\n\n    marker.position.set(entry.position.x, entry.position.y, entry.position.z)\n    marker.userData.lightIndex = index\n    marker.userData.handleType = String(index)\n    ;(marker.material as THREE.MeshBasicMaterial).color.copy(color)\n    marker.scale.setScalar(\n      index === this.selectedIndex ? MARKER_SELECTED_SCALE : 1\n    )\n  }\n\n  private refreshHelperVisibility(): void {\n    this.rigs.forEach((rig, i) => {\n      rig.marker.visible = this.helpersOn\n      rig.helper.visible = this.helpersOn && i === this.selectedIndex\n    })\n  }\n\n  private updateHelpers(): void {\n    for (const rig of this.rigs) rig.helper.update?.()\n  }\n}\n\nfunction hasTargetObject(\n  light: SceneLight\n): light is THREE.DirectionalLight | THREE.SpotLight {\n  return (\n    light instanceof THREE.DirectionalLight || light instanceof THREE.SpotLight\n  )\n}\n\nfunction shadowBlurTexels(entry: LightInfoEntry): number {\n  const radius = Math.max(entry.radius ?? 0, 0)\n  return entry.type === 'directional'\n    ? radius * SHADOW_BLUR_TEXELS_PER_DEGREE\n    : radius * SHADOW_BLUR_TEXELS_PER_UNIT\n}\n\nfunction spotPenumbra(entry: LightInfoEntry): number {\n  const outer = Math.max(entry.outerConeAngle ?? 45, 1e-3)\n  const inner = Math.min(entry.innerConeAngle ?? 30, outer)\n  return Math.min(Math.max(1 - inner / outer, 0), 1)\n}\n","import { DEFAULT_CAMERA_INFO_STATE } from '@/extensions/core/cameraInfo/types'\nimport type { CameraInfoState } from '@/extensions/core/cameraInfo/types'\n\nimport { lightTarget } from './types'\nimport type { LightInfoEntry, Vec3 } from './types'\n\nconst DEG2RAD = Math.PI / 180\nconst RAD2DEG = 180 / Math.PI\n\nexport interface OrbitAngles {\n  yaw: number\n  pitch: number\n  distance: number\n}\n\nexport function orbitPosition(\n  target: Vec3,\n  yawDeg: number,\n  pitchDeg: number,\n  distance: number\n): Vec3 {\n  const yaw = yawDeg * DEG2RAD\n  const pitch = pitchDeg * DEG2RAD\n  const cosPitch = Math.cos(pitch)\n  return {\n    x: target.x + distance * cosPitch * Math.sin(yaw),\n    y: target.y + distance * Math.sin(pitch),\n    z: target.z + distance * cosPitch * Math.cos(yaw)\n  }\n}\n\nexport function orbitAnglesFor(position: Vec3, target: Vec3): OrbitAngles {\n  const dx = position.x - target.x\n  const dy = position.y - target.y\n  const dz = position.z - target.z\n  const horizontal = Math.hypot(dx, dz)\n  const distance = Math.max(Math.hypot(dx, dy, dz), 1e-6)\n  return {\n    yaw: Math.atan2(dx, dz) * RAD2DEG,\n    pitch: Math.atan2(dy, horizontal) * RAD2DEG,\n    distance\n  }\n}\n\nexport function orbitHandleState(\n  light: LightInfoEntry | null\n): CameraInfoState {\n  if (light?.type !== 'directional') {\n    return { ...DEFAULT_CAMERA_INFO_STATE, mode: 'look_at' }\n  }\n  const target = lightTarget(light)\n  return {\n    ...DEFAULT_CAMERA_INFO_STATE,\n    mode: 'orbit',\n    target,\n    orbit: orbitAnglesFor(light.position, target)\n  }\n}\n","import * as THREE from 'three'\n\nimport {\n  OrbitHandles,\n  isOrbitHandleType\n} from '@/extensions/core/cameraInfo/handles/OrbitHandles'\nimport type { OrbitHandleType } from '@/extensions/core/cameraInfo/handles/OrbitHandles'\nimport { TargetHandle } from '@/extensions/core/cameraInfo/handles/TargetHandle'\nimport { pickHandleAtPointer } from '@/extensions/core/cameraInfo/handles/handlePicking'\nimport {\n  pointToDistance,\n  pointToPitchAngle,\n  pointToYawAngle\n} from '@/extensions/core/cameraInfo/handles/orbitDragMath'\nimport type { Viewport3d } from '@/extensions/core/load3d/Viewport3d'\nimport { createViewport3d } from '@/extensions/core/load3d/createViewport3d'\nimport type { Load3DOptions } from '@/extensions/core/load3d/interfaces'\n\nimport { LightInfoOverlay } from './LightInfoOverlay'\nimport {\n  orbitAnglesFor,\n  orbitHandleState,\n  orbitPosition\n} from './lightTransform'\nimport { lightTarget } from './types'\nimport type { LightInfoEntry, LightInfoType } from './types'\n\nexport type LightTransformGizmoMode = 'none' | 'light-position' | 'target'\n\nconst OUTPUT_VIEW = {\n  position: { x: 0, y: 6, z: 8 },\n  target: { x: 0, y: -0.5, z: 0 },\n  fov: 35\n} as const\n\nexport interface LightInfoViewportOptions extends Load3DOptions {\n  onLightsChange?: (lights: LightInfoEntry[]) => void\n  onSelectLight?: (index: number) => void\n}\n\ninterface DragState {\n  type: OrbitHandleType\n  pointerId: number\n}\n\nexport class LightInfoViewport {\n  readonly viewport: Viewport3d\n  readonly overlay: LightInfoOverlay\n  readonly orbitHandles: OrbitHandles\n  readonly positionHandle: TargetHandle\n  readonly targetHandle: TargetHandle\n\n  private readonly onLightsChange?: LightInfoViewportOptions['onLightsChange']\n  private readonly onSelectLight?: LightInfoViewportOptions['onSelectLight']\n  private readonly raycaster = new THREE.Raycaster()\n  private readonly pointer = new THREE.Vector2()\n\n  private dragState: DragState | null = null\n  private hoveredHandle: OrbitHandleType | null = null\n  private hoveredMarker = false\n  private gizmosOn = true\n  private cameraLocked = false\n  private transformGizmoMode: LightTransformGizmoMode = 'none'\n\n  constructor(\n    container: HTMLElement,\n    initialLights: LightInfoEntry[] = [],\n    options?: LightInfoViewportOptions\n  ) {\n    this.onLightsChange = options?.onLightsChange\n    this.onSelectLight = options?.onSelectLight\n    this.viewport = createViewport3d(container, options)\n    this.viewport.viewHelperManager.visibleViewHelper(false)\n    this.viewport.sceneManager.toggleGrid(false)\n    this.viewport.lightingManager.setLightIntensity(0)\n    this.viewport.renderer.shadowMap.enabled = true\n    this.viewport.renderer.shadowMap.type = THREE.PCFShadowMap\n\n    this.overlay = new LightInfoOverlay(initialLights)\n    this.viewport.setOverlay(this.overlay)\n\n    this.orbitHandles = new OrbitHandles()\n    this.orbitHandles.attach(this.viewport.sceneManager.scene)\n\n    this.positionHandle = new TargetHandle(\n      this.viewport.cameraManager.activeCamera,\n      this.viewport.domElement,\n      (dragging) => {\n        this.viewport.controlsManager.controls.enabled =\n          !dragging && !this.cameraLocked\n      },\n      (position) => {\n        this.mutateSelected((light) => ({\n          ...light,\n          position: { ...position }\n        }))\n      },\n      'LightInfoPosition'\n    )\n    this.positionHandle.attach(this.viewport.sceneManager.scene)\n\n    this.targetHandle = new TargetHandle(\n      this.viewport.cameraManager.activeCamera,\n      this.viewport.domElement,\n      (dragging) => {\n        this.viewport.controlsManager.controls.enabled =\n          !dragging && !this.cameraLocked\n      },\n      (target) => {\n        this.mutateSelected((light) => ({ ...light, target: { ...target } }))\n      },\n      'LightInfoTarget'\n    )\n    this.targetHandle.attach(this.viewport.sceneManager.scene)\n\n    this.syncHandles()\n    this.attachPointerHandlers()\n  }\n\n  applyLights(lights: LightInfoEntry[], selectedIndex: number): void {\n    this.overlay.applyLights(lights, selectedIndex)\n    this.syncHandles()\n    this.refreshGizmoVisibility()\n    this.viewport.forceRender()\n  }\n\n  setGizmosVisible(on: boolean): void {\n    if (this.gizmosOn === on) return\n    this.gizmosOn = on\n    this.overlay.setHelpersVisible(on)\n    this.refreshGizmoVisibility()\n    this.viewport.forceRender()\n  }\n\n  setTransformGizmoMode(mode: LightTransformGizmoMode): void {\n    if (this.transformGizmoMode === mode) return\n    this.transformGizmoMode = mode\n    this.refreshGizmoVisibility()\n    this.viewport.forceRender()\n  }\n\n  resetViewToOutput(): void {\n    this.viewport.setCameraState({\n      position: new THREE.Vector3(\n        OUTPUT_VIEW.position.x,\n        OUTPUT_VIEW.position.y,\n        OUTPUT_VIEW.position.z\n      ),\n      target: new THREE.Vector3(\n        OUTPUT_VIEW.target.x,\n        OUTPUT_VIEW.target.y,\n        OUTPUT_VIEW.target.z\n      ),\n      zoom: 1,\n      cameraType: 'perspective',\n      fov: OUTPUT_VIEW.fov\n    })\n    this.viewport.forceRender()\n  }\n\n  setCameraLocked(locked: boolean): void {\n    if (this.cameraLocked === locked) return\n    this.cameraLocked = locked\n    this.viewport.controlsManager.controls.enabled = !locked\n  }\n\n  remove(): void {\n    this.detachPointerHandlers()\n    this.canvas.style.cursor = ''\n    this.orbitHandles.dispose()\n    this.positionHandle.dispose()\n    this.targetHandle.dispose()\n    this.viewport.remove()\n  }\n\n  private get selectedLight(): LightInfoEntry | null {\n    return this.overlay.getSelectedLight()\n  }\n\n  private mutateSelected(\n    mutate: (light: LightInfoEntry) => LightInfoEntry\n  ): void {\n    const lights = this.overlay.getLights()\n    const index = this.overlay.getSelectedIndex()\n    if (index < 0 || !lights[index]) return\n    lights[index] = mutate(lights[index])\n    this.applyLights(lights, index)\n    this.onLightsChange?.(lights)\n  }\n\n  private syncHandles(): void {\n    const light = this.selectedLight\n    this.orbitHandles.update(orbitHandleState(light))\n    if (!light) return\n    this.positionHandle.setTarget(light.position)\n    this.targetHandle.setTarget(lightTarget(light))\n  }\n\n  private refreshGizmoVisibility(): void {\n    const type = this.gizmosOn ? (this.selectedLight?.type ?? null) : null\n    this.orbitHandles.setVisible(type === 'directional')\n    this.positionHandle.setVisible(\n      this.transformGizmoMode === 'light-position' &&\n        type !== null &&\n        lightPositionApplies(type)\n    )\n    this.targetHandle.setVisible(\n      this.transformGizmoMode === 'target' &&\n        type !== null &&\n        targetApplies(type)\n    )\n  }\n\n  private get canvas(): HTMLCanvasElement {\n    return this.viewport.domElement\n  }\n\n  private attachPointerHandlers(): void {\n    const canvas = this.canvas\n    canvas.addEventListener('pointerdown', this.onPointerDown)\n    canvas.addEventListener('pointermove', this.onPointerMove)\n    canvas.addEventListener('pointerup', this.onPointerUp)\n    canvas.addEventListener('pointercancel', this.onPointerUp)\n    canvas.addEventListener('pointerleave', this.onPointerLeave)\n  }\n\n  private detachPointerHandlers(): void {\n    const canvas = this.canvas\n    canvas.removeEventListener('pointerdown', this.onPointerDown)\n    canvas.removeEventListener('pointermove', this.onPointerMove)\n    canvas.removeEventListener('pointerup', this.onPointerUp)\n    canvas.removeEventListener('pointercancel', this.onPointerUp)\n    canvas.removeEventListener('pointerleave', this.onPointerLeave)\n  }\n\n  private readonly onPointerLeave = (): void => {\n    if (this.dragState) return\n    this.setHoveredHandle(null)\n    this.setHoveredMarker(false)\n  }\n\n  private updatePointer(event: PointerEvent): void {\n    const rect = this.canvas.getBoundingClientRect()\n    this.pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1\n    this.pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1\n  }\n\n  private pickHandle(event: PointerEvent): OrbitHandleType | null {\n    if (!this.gizmosOn) return null\n    if (this.selectedLight?.type !== 'directional') return null\n    this.updatePointer(event)\n    const picked = pickHandleAtPointer(\n      this.raycaster,\n      this.pointer,\n      this.viewport.cameraManager.activeCamera,\n      this.orbitHandles.pickableMeshes(),\n      this.canvas\n    )\n    return picked !== null && isOrbitHandleType(picked) ? picked : null\n  }\n\n  private pickMarker(event: PointerEvent): number | null {\n    if (!this.gizmosOn) return null\n    this.updatePointer(event)\n    const picked = pickHandleAtPointer(\n      this.raycaster,\n      this.pointer,\n      this.viewport.cameraManager.activeCamera,\n      this.overlay.markerMeshes(),\n      this.canvas\n    )\n    if (picked === null) return null\n    const index = Number(picked)\n    return Number.isInteger(index) ? index : null\n  }\n\n  private setHoveredHandle(type: OrbitHandleType | null): void {\n    if (this.hoveredHandle === type) return\n    this.hoveredHandle = type\n    this.orbitHandles.setHovered(type)\n    this.refreshCursor()\n    this.viewport.forceRender()\n  }\n\n  private setHoveredMarker(hovered: boolean): void {\n    if (this.hoveredMarker === hovered) return\n    this.hoveredMarker = hovered\n    this.refreshCursor()\n  }\n\n  private refreshCursor(): void {\n    this.canvas.style.cursor = this.hoveredHandle\n      ? 'grab'\n      : this.hoveredMarker\n        ? 'pointer'\n        : ''\n  }\n\n  private readonly onPointerDown = (event: PointerEvent): void => {\n    if (event.button !== 0) return\n    const type = this.pickHandle(event)\n    if (type) {\n      this.setHoveredHandle(type)\n      this.dragState = { type, pointerId: event.pointerId }\n      this.canvas.setPointerCapture(event.pointerId)\n      this.canvas.style.cursor = 'grabbing'\n      this.viewport.controlsManager.controls.enabled = false\n      event.stopPropagation()\n      return\n    }\n    const markerIndex = this.pickMarker(event)\n    if (markerIndex === null) return\n    if (markerIndex !== this.overlay.getSelectedIndex()) {\n      this.applyLights(this.overlay.getLights(), markerIndex)\n      this.onSelectLight?.(markerIndex)\n    }\n    event.stopPropagation()\n  }\n\n  private readonly onPointerMove = (event: PointerEvent): void => {\n    if (!this.dragState) {\n      const handle = this.pickHandle(event)\n      this.setHoveredHandle(handle)\n      this.setHoveredMarker(!handle && this.pickMarker(event) !== null)\n      return\n    }\n    if (event.pointerId !== this.dragState.pointerId) return\n\n    this.updatePointer(event)\n    this.raycaster.setFromCamera(\n      this.pointer,\n      this.viewport.cameraManager.activeCamera\n    )\n\n    const light = this.selectedLight\n    if (!light) return\n    const plane = this.orbitHandles.dragPlaneFor(\n      this.dragState.type,\n      orbitHandleState(light)\n    )\n    const point = new THREE.Vector3()\n    if (!this.raycaster.ray.intersectPlane(plane, point)) return\n\n    const handleType = this.dragState.type\n    this.mutateSelected((current) => applyOrbitDrag(handleType, current, point))\n  }\n\n  private readonly onPointerUp = (event: PointerEvent): void => {\n    if (!this.dragState || event.pointerId !== this.dragState.pointerId) return\n    if (this.canvas.hasPointerCapture(event.pointerId)) {\n      this.canvas.releasePointerCapture(event.pointerId)\n    }\n    this.dragState = null\n    this.viewport.controlsManager.controls.enabled = !this.cameraLocked\n    this.refreshCursor()\n  }\n}\n\nfunction applyOrbitDrag(\n  type: OrbitHandleType,\n  light: LightInfoEntry,\n  point: THREE.Vector3\n): LightInfoEntry {\n  const target = lightTarget(light)\n  const angles = orbitAnglesFor(light.position, target)\n  if (type === 'yaw') {\n    angles.yaw = pointToYawAngle(point, target)\n  } else if (type === 'pitch') {\n    angles.pitch = pointToPitchAngle(point, target, angles.yaw)\n  } else {\n    angles.distance = pointToDistance(point, target, angles.yaw, angles.pitch)\n  }\n  return {\n    ...light,\n    position: orbitPosition(target, angles.yaw, angles.pitch, angles.distance)\n  }\n}\n\nexport function lightPositionApplies(type: LightInfoType): boolean {\n  return type === 'point' || type === 'spot'\n}\n\nexport function targetApplies(type: LightInfoType): boolean {\n  return type === 'directional' || type === 'spot'\n}\n","<template>\n  <div class=\"pointer-events-none absolute inset-0 flex flex-col\">\n    <div\n      class=\"pointer-events-auto flex h-10 items-center gap-1 bg-interface-menu-surface px-2\"\n      @wheel.stop\n    >\n      <Button\n        variant=\"textonly\"\n        size=\"unset\"\n        :tooltip=\"gizmosLabel\"\n        tooltip-side=\"bottom\"\n        type=\"button\"\n        :class=\"actionClass(gizmosOn)\"\n        :aria-pressed=\"gizmosOn\"\n        :aria-label=\"gizmosLabel\"\n        @click=\"gizmosOn = !gizmosOn\"\n      >\n        <i\n          :class=\"\n            cn(\n              'size-4',\n              gizmosOn ? 'icon-[lucide--eye]' : 'icon-[lucide--eye-off]'\n            )\n          \"\n        />\n        <span v-if=\"!compact\">{{ gizmosLabel }}</span>\n      </Button>\n      <div class=\"mx-1 h-5 w-px shrink-0 bg-interface-menu-stroke\" />\n      <Button\n        v-for=\"option in transformGizmoOptions\"\n        :key=\"option.value\"\n        variant=\"textonly\"\n        size=\"unset\"\n        :tooltip=\"$t(option.labelKey)\"\n        tooltip-side=\"bottom\"\n        type=\"button\"\n        :disabled=\"!option