cn(\n              'size-4',\n              cameraLocked ? 'icon-[lucide--lock]' : 'icon-[lucide--lock-open]'\n            )\n          \"\n        />\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { actionClass } from '@/components/load3d/menubar/menuBarStyles'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { LightTransformGizmoMode } from '@/extensions/core/lightInfo/LightInfoViewport'\nimport {\n  lightPositionApplies,\n  targetApplies\n} from '@/extensions/core/lightInfo/LightInfoViewport'\nimport type { LightInfoType } from '@/extensions/core/lightInfo/types'\n\nconst { compact, lightType } = defineProps<{\n  compact: boolean\n  lightType: LightInfoType | null\n}>()\n\nconst gizmosOn = defineModel<boolean>('gizmosOn', { required: true })\nconst transformGizmoMode = defineModel<LightTransformGizmoMode>(\n  'transformGizmoMode',\n  { required: true }\n)\nconst cameraLocked = defineModel<boolean>('cameraLocked', { required: true })\n\nconst emit = defineEmits<{\n  resetView: []\n}>()\n\nconst { t } = useI18n()\n\nconst gizmosLabel = computed(() =>\n  gizmosOn.value ? t('load3d.hideGizmos') : t('load3d.showGizmos')\n)\n\nconst cameraLockLabel = computed(() =>\n  cameraLocked.value ? t('load3d.unlockCamera') : t('load3d.lockCamera')\n)\n\nconst transformGizmoOptions = computed(() => [\n  {\n    value: 'none' as const,\n    labelKey: 'load3d.transformGizmo.none',\n    icon: 'icon-[lucide--ban]',\n    enabled: true\n  },\n  {\n    value: 'light-position' as const,\n    labelKey: 'load3d.transformGizmo.lightPosition',\n    icon: 'icon-[lucide--move-3d]',\n    enabled: lightType !== null && lightPositionApplies(lightType)\n  },\n  {\n    value: 'target' as const,\n    labelKey: 'load3d.transformGizmo.target',\n    icon: 'icon-[lucide--target]',\n    enabled: lightType !== null && targetApplies(lightType)\n  }\n])\n\nconst effectiveTransformGizmoMode = computed<LightTransformGizmoMode>(() =>\n  transformGizmoOptions.value.some(\n    ({ value, enabled }) => value === transformGizmoMode.value && enabled\n  )\n    ? transformGizmoMode.value\n    : 'none'\n)\n</script>\n","import { computed, ref, toRaw, unref } from 'vue'\nimport type { MaybeRef } from 'vue'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport {\n  createSceneHoverHandlers,\n  useViewportNodeWiring\n} from '@/composables/useViewportNodeWiring'\nimport {\n  getNodeWidgetValue,\n  setNodeWidgetValue\n} from '@/core/graph/widgets/nodeWidgetValues'\nimport { LightInfoViewport } from '@/extensions/core/lightInfo/LightInfoViewport'\nimport type { LightTransformGizmoMode } from '@/extensions/core/lightInfo/LightInfoViewport'\nimport { normalizeLightsValue } from '@/extensions/core/lightInfo/lightsValue'\nimport {\n  cloneLights,\n  createDefaultLight\n} from '@/extensions/core/lightInfo/types'\nimport type {\n  LightInfoEntry,\n  LightInfoType\n} from '@/extensions/core/lightInfo/types'\nimport { t } from '@/i18n'\nimport { onGraphIntent } from '@/lib/litegraph/src/graphIntents'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { reportError } from '@/platform/telemetry/reportError'\n\nconst EDITOR_WIDGET_NAME = 'editor_state'\n\nexport function useLightInfo(nodeRef: MaybeRef<LGraphNode | null>) {\n  let viewport: LightInfoViewport | null = null\n  let host: LGraphNode | null = null\n  let stopObserving: (() => void) | null = null\n  const wiring = useViewportNodeWiring()\n  let suppressEcho = false\n\n  const lights = ref<LightInfoEntry[]>([])\n  const selectedIndex = ref(-1)\n\n  const selectedLight = computed<LightInfoEntry | null>(\n    () => lights.value[selectedIndex.value] ?? null\n  )\n\n  const initialize = (container: HTMLElement): void => {\n    const raw = toRaw(unref(nodeRef))\n    if (!raw) return\n    if (viewport) cleanup()\n\n    try {\n      host = raw\n      lights.value = normalizeLightsValue(\n        getNodeWidgetValue(raw, EDITOR_WIDGET_NAME)\n      )\n      selectedIndex.value = lights.value.length ? 0 : -1\n      viewport = new LightInfoViewport(container, lights.value, {\n        onLightsChange: (next) => {\n          lights.value = next\n          writeWidgetValue(next)\n        },\n        onSelectLight: (index) => {\n          selectedIndex.value = index\n        }\n      })\n      viewport.applyLights(lights.value, selectedIndex.value)\n      observeExternalChanges(raw)\n      wiring.wireNode(raw, { viewport: () => viewport?.viewport })\n    } catch (error) {\n      reportError(error, {\n        errorType: 'failure_initializing_light_info_viewport',\n        surface: 'graph'\n      })\n      cleanup()\n      useToast().warning(t('toastMessages.failedToInitializeLightInfoViewer'))\n    }\n  }\n\n  const cleanup = (): void => {\n    stopObserving?.()\n    stopObserving = null\n    wiring.unwire()\n    host = null\n    viewport?.remove()\n    viewport = null\n  }\n\n  const { handleMouseEnter, handleMouseLeave } = createSceneHoverHandlers(\n    () => viewport?.viewport\n  )\n\n  const setGizmosVisible = (on: boolean): void => {\n    viewport?.setGizmosVisible(on)\n  }\n\n  const setTransformGizmoMode = (mode: LightTransformGizmoMode): void => {\n    viewport?.setTransformGizmoMode(mode)\n  }\n\n  const resetViewToOutput = (): void => {\n    viewport?.resetViewToOutput()\n  }\n\n  const setCameraLocked = (locked: boolean): void => {\n    viewport?.setCameraLocked(locked)\n  }\n\n  const selectLight = (index: number): void => {\n    if (index < 0 || index >= lights.value.length) return\n    selectedIndex.value = index\n    viewport?.applyLights(lights.value, index)\n  }\n\n  const addLight = (type: LightInfoType): void => {\n    const next = [...lights.value, createDefaultLight(type)]\n    selectedIndex.value = next.length - 1\n    commit(next)\n  }\n\n  const removeSelectedLight = (): void => {\n    if (selectedIndex.value < 0) return\n    const next = [...lights.value]\n    next.splice(selectedIndex.value, 1)\n    selectedIndex.value = Math.min(selectedIndex.value, next.length - 1)\n    commit(next)\n  }\n\n  const updateSelectedLight = (patch: Partial<LightInfoEntry>): void => {\n    const current = selectedLight.value\n    if (!current) return\n    const next = [...lights.value]\n    next[selectedIndex.value] = normalizeLightsValue([\n      { ...current, ...patch }\n    ])[0]\n    commit(next)\n  }\n\n  const setSelectedLightType = (type: LightInfoType): void => {\n    const current = selectedLight.value\n    if (!current || current.type === type) return\n    const base = createDefaultLight(type)\n    const next = [...lights.value]\n    next[selectedIndex.value] = {\n      ...base,\n      color: current.color,\n      position: { ...current.position },\n      ...(base.target && current.target\n        ? { target: { ...current.target } }\n        : {})\n    }\n    commit(next)\n  }\n\n  function commit(next: LightInfoEntry[]): void {\n    lights.value = next\n    if (selectedIndex.value >= next.length) {\n      selectedIndex.value = next.length - 1\n    }\n    writeWidgetValue(next)\n    viewport?.applyLights(next, selectedIndex.value)\n  }\n\n  function writeWidgetValue(next: LightInfoEntry[]): void {\n    if (!host) return\n    suppressEcho = true\n    try {\n      setNodeWidgetValue(host, EDITOR_WIDGET_NAME, cloneLights(next))\n    } finally {\n      suppressEcho = false\n    }\n  }\n\n  function applyExternalValue(value: unknown): void {\n    if (suppressEcho || !viewport) return\n    lights.value = normalizeLightsValue(value)\n    if (selectedIndex.value >= lights.value.length) {\n      selectedIndex.value = lights.value.length - 1\n    } else if (selectedIndex.value < 0 && lights.value.length) {\n      selectedIndex.value = 0\n    }\n    viewport.applyLights(lights.value, selectedIndex.value)\n  }\n\n  function observeExternalChanges(target: LGraphNode): void {\n    const graphId = target.graph?.rootGraph.id\n    if (!graphId) return\n    stopObserving = onGraphIntent((intent) => {\n      if (\n        intent.type === 'set_widget' &&\n        intent.graphId === graphId &&\n        intent.nodeId === target.id &&\n        intent.name === EDITOR_WIDGET_NAME\n      ) {\n        applyExternalValue(intent.value)\n      }\n    })\n  }\n\n  return {\n    initialize,\n    cleanup,\n    handleMouseEnter,\n    handleMouseLeave,\n    setGizmosVisible,\n    setTransformGizmoMode,\n    resetViewToOutput,\n    setCameraLocked,\n    lights,\n    selectedIndex,\n    selectedLight,\n    selectLight,\n    addLight,\n    removeSelectedLight,\n    updateSelectedLight,\n    setSelectedLightType\n  }\n}\n","<template>\n  <div\n    class=\"flex size-full min-h-[300px] flex-col gap-1\"\n    @pointerdown.stop\n    @mousedown.stop\n    @contextmenu.stop.prevent\n  >\n    <div\n      ref=\"viewportArea\"\n      class=\"relative min-h-[220px] shrink-0\"\n      :style=\"{ height: `calc(100% - ${panelBudget}px)` }\"\n    >\n      <div\n        ref=\"container\"\n        class=\"relative size-full\"\n        data-capture-wheel=\"true\"\n        tabindex=\"-1\"\n        @pointerdown.stop=\"container?.focus()\"\n        @mouseenter=\"handleMouseEnter\"\n        @mouseleave=\"handleMouseLeave\"\n      />\n      <LightInfoViewportToolbar\n        v-model:gizmos-on=\"gizmosOn\"\n        v-model:transform-gizmo-mode=\"transformGizmoMode\"\n        v-model:camera-locked=\"cameraLocked\"\n        :compact\n        :light-type=\"selectedLight?.type ?? null\"\n        @reset-view=\"resetViewToOutput\"\n      />\n    </div>\n\n    <div\n      class=\"flex min-h-0 flex-1 flex-col gap-1 overflow-y-auto\"\n      data-capture-wheel=\"true\"\n    >\n      <div class=\"flex h-9 items-center gap-1 overflow-x-auto px-1\">\n        <Button\n          v-for=\"(light, index) in lights\"\n          :key=\"index\"\n          :tooltip=\"$t(LIGHT_TYPE_LABEL_KEYS[light.type])\"\n          variant=\"textonly\"\n          size=\"unset\"\n          :aria-pressed=\"index === selectedIndex\"\n          :aria-label=\"\n            $t('lightInfo.lightChip', {\n              index: chipNumber(index),\n              type: $t(LIGHT_TYPE_LABEL_KEYS[light.type])\n            })\n          \"\n          :class=\"lightChipClass(index === selectedIndex)\"\n          @click=\"selectLight(index)\"\n        >\n          <span\n            class=\"size-2.5 shrink-0 rounded-full\"\n            :style=\"{ backgroundColor: light.color }\"\n          />\n          {{ chipNumber(index) }}\n        </Button>\n        <Button\n          :tooltip=\"$t('lightInfo.addLight')\"\n          variant=\"textonly\"\n          size=\"icon\"\n          :aria-label=\"$t('lightInfo.addLight')\"\n          @click=\"addLight('directional')\"\n        >\n          <i class=\"icon-[lucide--plus] size-4\" />\n        </Button>\n        <Button\n          v-if=\"selectedLight\"\n          :tooltip=\"$t('lightInfo.removeLight')\"\n          variant=\"textonly\"\n          size=\"icon\"\n          :aria-label=\"$t('lightInfo.removeLight')\"\n          @click=\"removeSelectedLight\"\n        >\n          <i class=\"icon-[lucide--trash-2] size-4\" />\n        </Button>\n      </div>\n\n      <LightInfoLightEditor\n        v-if=\"selectedLight\"\n        :light=\"selectedLight\"\n        :compact\n        @update=\"updateSelectedLight\"\n        @change-type=\"setSelectedLightType\"\n      />\n      <div v-else class=\"px-2 pb-1 text-xs text-muted-foreground\">\n        {{ $t('lightInfo.noLights') }}\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useElementSize } from '@vueuse/core'\nimport { computed, onMounted, onUnmounted, ref, shallowRef, watch } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { chipClass } from '@/components/load3d/menubar/menuBarStyles'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { LightTransformGizmoMode } from '@/extensions/core/lightInfo/LightInfoViewport'\nimport { LIGHT_TYPE_LABEL_KEYS } from '@/extensions/core/lightInfo/types'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { NodeId } from '@/types/nodeId'\nimport { resolveNode } from '@/utils/litegraphUtil'\n\nimport LightInfoLightEditor from './LightInfoLightEditor.vue'\nimport LightInfoViewportToolbar from './LightInfoViewportToolbar.vue'\nimport { useLightInfo } from './useLightInfo'\n\nconst COMPACT_WIDTH_THRESHOLD = 480\nconst PANEL_BUDGET_WIDE = 208\nconst PANEL_BUDGET_COMPACT = 352\n\nfunction chipNumber(index: number) {\n  return String(index + 1).padStart(2, '0')\n}\n\nfunction lightChipClass(active: boolean) {\n  return cn(\n    chipClass,\n    'border border-transparent bg-transparent font-mono text-xs',\n    active\n      ? 'border-component-node-border bg-component-node-widget-background-selected text-base-foreground'\n      : 'text-muted-foreground hover:bg-button-hover-surface hover:text-base-foreground'\n  )\n}\n\nconst { nodeId } = defineProps<{\n  nodeId: NodeId\n}>()\n\nconst node = shallowRef<LGraphNode | null>(null)\nconst container = ref<HTMLElement | null>(null)\nconst viewportArea = ref<HTMLElement | null>(null)\nconst { width: viewportWidth } = useElementSize(viewportArea)\nconst compact = computed(\n  () => viewportWidth.value > 0 && viewportWidth.value < COMPACT_WIDTH_THRESHOLD\n)\nconst panelBudget = computed(() =>\n  compact.value ? PANEL_BUDGET_COMPACT : PANEL_BUDGET_WIDE\n)\nconst gizmosOn = ref(true)\nconst transformGizmoMode = ref<LightTransformGizmoMode>('none')\nconst cameraLocked = ref(false)\n\nconst {\n  initialize,\n  cleanup,\n  handleMouseEnter,\n  handleMouseLeave,\n  setGizmosVisible,\n  setTransformGizmoMode,\n  resetViewToOutput,\n  setCameraLocked,\n  lights,\n  selectedIndex,\n  selectedLight,\n  selectLight,\n  addLight,\n  removeSelectedLight,\n  updateSelectedLight,\n  setSelectedLightTy